bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i "$cid" node --input-type=module - <<'JS'
import {readFileSync} from 'node:fs';
const root='/opt/videobot/';
const load=p=>readFileSync(root+p,'utf8');
const ui=load('src/telegram/creatorUi.mjs');
const wizard=load('src/telegram/creatorWizard.mjs');
const processor=load('src/telegram/mediaProcessor.mjs');
const preview=load('src/sales/autoPreview.mjs');
const sample=load('src/sales/sampleMedia.mjs');
const results={
 oldDeepLink:ui.includes('start=ved_'),
 consentAction:ui.includes('同意して登録する'),
 sampleMontage:sample.includes('prepareAutomaticSampleVideo'),
 previewConnected:preview.includes('prepareAutomaticSampleVideo'),
 secondThumbnailConnected:processor.includes('secondThumbnailOutputPath'),
 fieldPanel:wizard.includes('creatorFieldPanel(draft,value,rev)')
};
console.log(JSON.stringify(results));
if(!results.sampleMontage||!results.previewConnected||!results.secondThumbnailConnected)process.exitCode=71;
else if(results.oldDeepLink||!results.consentAction)process.exitCode=72;
JS
